// Extract and validate incoming data from webhook
const rawInput = $input.first().json;

// The data could be directly in json (if testing) or in json.body (from actual webhook)
const data = rawInput.body || rawInput;

console.log('Received post-bclconvert callback for run:', data.run_id);
console.log('DRAGEN success:', data.dragen_success);

if (!data.run_id) {
  throw new Error('Missing run_id in webhook payload');
}

return [{ json: data }];

// Generate the copy-to-alldata script
// Read from Validate Input node which already extracted the data
const data = $('Validate Input1').first().json;

// Store payload as base64 to avoid quoting issues
const payloadJson = JSON.stringify(data);
const payloadBase64 = Buffer.from(payloadJson).toString('base64');

const scriptContent = `#!/bin/bash
# Stage 3: Copy FASTQ results to alldata storage
# Run ID: ${data.run_id}
# Generated: ${new Date().toISOString()}

set -o pipefail

RUN_ID="${data.run_id}"
SOURCE_DIR="/staging/tmp/${data.run_id}-Fastq"
DEST_DIR="/mnt/illuminastorage/fastq_folder/${data.run_id}-Fastq"
LOG_FILE="${data.scriptDir}/${data.run_id}_stage3_copy.log"
WEBHOOK_SUCCESS="${data.webhooks.postCopy}"
WEBHOOK_ERROR="${data.webhooks.errorHandler}"

# Payload stored as base64 to avoid quoting issues
PAYLOAD_BASE64="${payloadBase64}"

# Decode payload
PAYLOAD_BASE=$(echo "$PAYLOAD_BASE64" | base64 -d)

echo "=== Copy Results Script Started at $(date) ===" | tee "$LOG_FILE"
echo "Source: $SOURCE_DIR" | tee -a "$LOG_FILE"
echo "Destination: $DEST_DIR" | tee -a "$LOG_FILE"
echo "" | tee -a "$LOG_FILE"

# Run rsync to copy results
rsync -avh "$SOURCE_DIR/" "$DEST_DIR/" 2>&1 | tee -a "$LOG_FILE"
EXIT_CODE=\${PIPESTATUS[0]}

echo "" | tee -a "$LOG_FILE"
echo "=== Copy Results Script Finished at $(date) with exit code $EXIT_CODE ===" | tee -a "$LOG_FILE"

# Callback based on result
if [ "$EXIT_CODE" -eq 0 ]; then
    echo "Copy completed successfully, calling success webhook..." | tee -a "$LOG_FILE"
    SUCCESS_PAYLOAD=$(echo "$PAYLOAD_BASE" | jq '. + {copy_success: true}')
    curl -s -X POST "$WEBHOOK_SUCCESS" -H "Content-Type: application/json" -d "$SUCCESS_PAYLOAD" | tee -a "$LOG_FILE"
    echo "" | tee -a "$LOG_FILE"
else
    echo "Copy failed, calling error webhook..." | tee -a "$LOG_FILE"
    ERROR_PAYLOAD=$(echo "$PAYLOAD_BASE" | jq --arg ec "$EXIT_CODE" --arg stage "copy_results" '. + {error_stage: $stage, exit_code: ($ec|tonumber), error_message: "rsync to alldata failed", copy_success: false}')
    curl -s -X POST "$WEBHOOK_ERROR" -H "Content-Type: application/json" -d "$ERROR_PAYLOAD" | tee -a "$LOG_FILE"
    echo "" | tee -a "$LOG_FILE"
fi

echo "Webhook called, script complete." | tee -a "$LOG_FILE"
`;

// Encode the entire script as base64 for safe transfer
const scriptBase64 = Buffer.from(scriptContent).toString('base64');

return [{
  json: {
    ...data,
    copyScript: scriptContent,
    copyScriptBase64: scriptBase64,
    copyScriptPath: `${data.scriptDir}/${data.run_id}_stage3_copy.sh`
  }
}];

